<template><section><h2 class="text-2xl font-bold">Danh sách sản phẩm</h2><p class="text-gray-400 mt-1">Chỉ xem dữ liệu; không có thao tác chỉnh sửa.</p><div class="flex gap-3 mt-5"><input v-model="keyword" class="rounded bg-white/10 border border-white/20 p-2" placeholder="Tìm tên sản phẩm"/><button class="px-4 py-2 rounded bg-primary text-secondary" @click="page=0;load()">Tìm kiếm</button></div><p v-if="error" class="mt-4 text-error">{{error}}</p><p v-else-if="loading" class="mt-4 text-gray-400">Đang tải…</p><Table v-else :columns="columns" :data="items" class="mt-4"><template #remainingQuantity="{row}">{{row.remainingQuantity}} {{row.unit}}</template></Table><div class="mt-4 flex justify-between text-sm text-gray-400"><span>Tổng: {{total}}</span><div class="flex gap-2"><button :disabled="page===0" @click="page--;load()">Trước</button><span>Trang {{page+1}}</span><button :disabled="items.length < size" @click="page++;load()">Sau</button></div></div></section></template><script setup>import{onMounted,ref}from'vue';import Table from'../../components/ui/Table.vue';import{adminApi}from'../../api/adminService';const items=ref([]),keyword=ref(''),loading=ref(true),error=ref(''),page=ref(0),size=10,total=ref(0);const columns=[{key:'productId',label:'Mã'},{key:'productName',label:'Sản phẩm'},{key:'farmName',label:'Trang trại'},{key:'cropName',label:'Cây trồng'},{key:'remainingQuantity',label:'Số lượng còn lại'},{key:'unit',label:'Đơn vị'}];const load=async()=>{loading.value=true;error.value='';try{const{data}=await adminApi.products({keyword:keyword.value||undefined,page:page.value,size});items.value=data.content;total.value=data.totalElements}catch(e){error.value=e.response?.data?.message||'Không thể tải sản phẩm.'}finally{loading.value=false}};onMounted(load)</script>
